<?php
function ix_require($action){if(!can_action($action))throw new Exception('Your role cannot perform this action.');}
function ix_damage_plan($input){ix_require('ix_damage');packaging_require();$date=process_date($input['txn_date']??'');if($date>date('Y-m-d'))throw new Exception('Damage date cannot be in the future.');require_open_inventory_date($date);$pid=whole_number($input['product_id']??'','Product',1);$p=active_product($pid);$qty=whole_number($input['qty']??'','Damaged quantity',1);$pl=stock_platform($input['platform']??'');$reason=process_reason($input['reason']??'');if(mb_strlen($reason)>2000)throw new Exception('Reason is too long.');check_platform_alignment($pid);unset($GLOBALS['OM_RESERVED']);om_assert_available($pid,$qty);om_assert_available($pid,$qty,$pl);$s=stock_row($pid);$x=['date'=>$date,'pid'=>$pid,'sku'=>$p['master_sku'],'name'=>$p['name'],'qty'=>$qty,'platform'=>$pl,'reason'=>$reason,'sellable'=>(int)$s['current'],'non'=>(int)$s['nonsellable'],'physical'=>(int)$s['physical'],'allocated'=>platform_qty($pl,$pid),'available'=>om_available($pid,$pl)];$x['digest']=hash('sha256',json_encode($x));return $x;}
function ix_damage_post($saved,$ack){ix_require('ix_damage');if(!$ack)throw new Exception('Confirm the identified damaged/leaking items.');$key=$saved['key']??'';if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new Exception('Review the declaration again.');return process_transaction(function()use($saved,$key){if($old=studio_query('SELECT id FROM non_sellable WHERE packaging_receipt_key=?',[$key])->fetchColumn())throw new Exception('Declaration already posted: NS-'.$old.'. No second deduction.');$s=$saved['plan'];studio_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$s['pid']]);$p=ix_damage_plan(['txn_date'=>$s['date'],'product_id'=>$s['pid'],'qty'=>$s['qty'],'platform'=>$s['platform'],'reason'=>$s['reason']]);if(!hash_equals($s['digest'],$p['digest']))throw new Exception('Stocks / reservations changed. Review the declaration again.');$ref='DAMAGE-'.date('Ymd-His').'-'.substr($key,0,8);studio_query("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id,packaging_receipt_key) VALUES(?,?,?,?,?,'Damaged / Leak','Quarantine','For Review','Warehouse Condition',1,?,?,?)",[$p['date'],$p['platform'],$ref,$p['pid'],$p['qty'],$p['reason'],current_user()['id'],$key]);$id=(int)db()->lastInsertId();change_platform_stock($p['platform'],$p['pid'],-$p['qty'],$ref,$p['date']);check_platform_alignment($p['pid']);$after=stock_row($p['pid']);if((int)$after['physical']!==$p['physical'])throw new Exception('Physical stock reconciliation failed.');audit('Declare sellable damage / leak','Non-Sellable','NS-'.$id,$ref.'; '.$p['sku'].'; '.$p['reason'].'; Sellable '.$p['sellable'].' → '.$after['current'].'; Non-Sellable '.$p['non'].' → '.$after['nonsellable'].'; Physical unchanged '.$after['physical']);return $id;});}
function ix_cases_ready(){if(!array_key_exists('IX_READY',$GLOBALS)){$tables=db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$GLOBALS['IX_READY']=!array_diff(['return_investigations','return_investigation_events'],$tables);}return $GLOBALS['IX_READY'];}
function ix_case_install(){ix_require('ix_setup');db()->exec("CREATE TABLE IF NOT EXISTS return_investigations(id BIGINT AUTO_INCREMENT PRIMARY KEY,case_ref VARCHAR(100) NOT NULL UNIQUE,platform VARCHAR(40) NOT NULL,order_no VARCHAR(100) NOT NULL,order_record_id BIGINT NULL,tracking_no VARCHAR(100) NOT NULL,actual_product_id INT NULL,actual_description VARCHAR(500) NOT NULL,received_qty INT NOT NULL,received_date DATE NOT NULL,status VARCHAR(30) NOT NULL,reason TEXT NOT NULL,evidence_path VARCHAR(500) NULL,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,revision INT NOT NULL DEFAULT 1,UNIQUE(platform,tracking_no),INDEX(order_record_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");db()->exec("CREATE TABLE IF NOT EXISTS return_investigation_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,case_id BIGINT NOT NULL,event_type VARCHAR(60) NOT NULL,user_id INT NOT NULL,details_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(case_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");unset($GLOBALS['IX_READY']);audit('Enable wrong return cases','System','Return Investigations','Additive case/evidence journal; no inventory posting.');}
function ix_case($id,$lock=false){if(!ix_cases_ready())throw new Exception('Ask Admin to enable Wrong Item Return Cases.');$r=studio_query('SELECT c.*,u.name creator FROM return_investigations c LEFT JOIN users u ON u.id=c.created_by WHERE c.id=?'.($lock?' FOR UPDATE':''),[(int)$id])->fetch();if(!$r)throw new Exception('Return case not found.');return $r;}
function ix_parcel_guard($platform,$references){if(!ix_cases_ready())return;$refs=[];foreach($references as $ref){$ref=mb_strtoupper(trim((string)$ref));if($ref!=='')$refs[]=$ref;}if(!$refs)return;$q=studio_query('SELECT case_ref FROM return_investigations WHERE platform=? AND tracking_no IN ('.implode(',',array_fill(0,count($refs),'?')).') LIMIT 1',array_merge([$platform],$refs));if($ref=$q->fetchColumn())throw new Exception('Parcel is a Wrong Item Return case: '.$ref.'. Do not credit it as the original item.');}
function ix_case_create($input,$file=null){ix_require('ix_case_create');if(!ix_cases_ready())throw new Exception('Ask Admin to enable Wrong Item Return Cases.');$pl=stock_platform($input['platform']??'');$number=trim((string)($input['order_no']??''));if($number===''||mb_strlen($number)>100)throw new Exception('Enter the original Order ID / Booking SN.');$tracking=mb_strtoupper(ur_tracking_no($input['tracking_no']??''));if($tracking==='')throw new Exception('Tracking / returned parcel reference is required.');$date=process_date($input['received_date']??'');if($date>date('Y-m-d'))throw new Exception('Received date cannot be in the future.');$status=$input['status']??'For Investigation';if(!in_array($status,['For Investigation','For Claims'],true))throw new Exception('Choose For Investigation or For Claims.');$desc=trim((string)($input['actual_description']??''));if(mb_strlen($desc)<3||mb_strlen($desc)>500)throw new Exception('Describe the actual item received (3–500 characters).');$qty=whole_number($input['received_qty']??'','Received quantity',1);$reason=process_reason($input['reason']??'');$pid=null;if(trim((string)($input['actual_sku']??''))!==''){$p=studio_query('SELECT id FROM products WHERE master_sku=?',[trim($input['actual_sku'])])->fetch();if(!$p)throw new Exception('Actual SKU is not recognized. Leave it blank for an unidentified item.');$pid=(int)$p['id'];}$o=or_find_reference($pl,om_shops()[$pl],$number);if($o)$number=$o['order_no'];return process_transaction(function()use($pl,$number,$tracking,$date,$status,$desc,$qty,$reason,$pid,$o,$file){if($existing=studio_query('SELECT id FROM return_investigations WHERE platform=? AND tracking_no=? FOR UPDATE',[$pl,$tracking])->fetchColumn())throw new Exception('This parcel already has case #'.$existing.'. Open the existing case.');foreach(studio_query("SELECT id,batch_ref,rows_json FROM return_batches WHERE status IN ('Review','Posted')") as $b)foreach(json_decode($b['rows_json'],true)?:[] as $r)if(($r['platform']??'')===$pl&&in_array($tracking,array_map(fn($v)=>mb_strtoupper(trim((string)$v)),[$r['tracking_no']??'',$r['receipt_reference']??'']),true))throw new Exception('This parcel is already in return batch '.$b['batch_ref'].'. Review that receipt before opening a case.');$path=null;if($file&&!empty($file['tmp_name'])){validate_upload_file($file,['pdf','png','jpg','jpeg']);$path=store_upload($file,'return_investigations','CASE');}$ref=next_ref('CASE').'-'.bin2hex(random_bytes(3));studio_query('INSERT INTO return_investigations(case_ref,platform,order_no,order_record_id,tracking_no,actual_product_id,actual_description,received_qty,received_date,status,reason,evidence_path,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$ref,$pl,$number,$o['id']??null,$tracking,$pid,$desc,$qty,$date,$status,$reason,$path,current_user()['id']]);$id=(int)db()->lastInsertId();$expected=[];if($o)foreach(studio_query('SELECT source_json,components_json FROM om_lines WHERE order_id=?',[$o['id']]) as $line)$expected[]=json_decode($line['source_json'],true)['name']??'Registered item';$detail=['status'=>$status,'expected_items'=>$expected,'actual_item'=>$desc,'actual_product_id'=>$pid,'received_qty'=>$qty,'tracking'=>$tracking,'remarks'=>$reason,'stock_effect'=>'No inventory credit; wrong parcel held separately for investigation / claims'];studio_query('INSERT INTO return_investigation_events(case_id,event_type,user_id,details_json) VALUES(?,?,?,?)',[$id,'Wrong item physically received',current_user()['id'],json_encode($detail)]);if($o)om_event($o['id'],null,'Wrong return item — '.$status,['reference'=>$ref,'reason'=>$reason,'actual_item'=>$desc,'received_qty'=>$qty,'stock_changed'=>false]);audit('Wrong return item recorded','Return',$ref,$status.'; '.$pl.' / '.$number.'; '.$tracking.'; no inventory credit.');return $id;});}
function ix_case_update($id,$input){ix_require('ix_case_update');$status=$input['status']??'';if(!in_array($status,['For Investigation','For Claims'],true))throw new Exception('Select a valid case status.');$note=process_reason($input['reason']??'');return process_transaction(function()use($id,$input,$status,$note){$r=ix_case($id,true);if((int)$r['revision']!==(int)($input['revision']??0))throw new Exception('Case changed. Refresh it first.');studio_query('UPDATE return_investigations SET status=?,revision=revision+1 WHERE id=?',[$status,$id]);studio_query('INSERT INTO return_investigation_events(case_id,event_type,user_id,details_json) VALUES(?,?,?,?)',[$id,'Case status / remarks updated',current_user()['id'],json_encode(['before'=>$r['status'],'status'=>$status,'remarks'=>$note,'stock_effect'=>'No inventory change'])]);if($r['order_record_id'])om_event($r['order_record_id'],null,'Wrong return case updated',['reference'=>$r['case_ref'],'reason'=>$status.'; '.$note,'stock_changed'=>false]);audit('Wrong return case updated','Return',$r['case_ref'],$status.'; '.$note.'; no inventory change.');});}
